        Node("HealingFlames", None, (1, 1), kind="Spell", spell="HealingFlames", pre=["PhoenixDive"]),
        Node("WarmEmbrace", "warm embrace", (3, 1), ranks=3, pre=["PhoenixDive", "CinderFeathers"], pct={"AA_HealingPower": 0.06}),
